/*
 * Zephyr ADC example: read a single channel and output the voltage in mV.
 *
 * Target board: nrf52840dk/nrf52840
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/devicetree.h>
#include <zephyr/sys/printk.h>

/* Get the ADC spec from devicetree (the node named "zephyr_user") */
#define ADC_SPEC ADC_DT_SPEC_GET(DT_PATH(zephyr_user))

int main(void)
{
	/* Grab the ADC device specification */
	const struct adc_dt_spec spec = ADC_SPEC;

	/* Make sure the ADC device is ready */
	if (!device_is_ready(spec.dev)) {
		printk("ADC device not ready\n");
		return 0;
	}

	/* Configure the channel before reading */
	int ret = adc_channel_setup_dt(&spec);
	if (ret) {
		printk("adc_channel_setup_dt failed: %d\n", ret);
		return 0;
	}

	/* Sample buffer and sequence setup */
	int16_t buf = 0;
	const struct adc_sequence seq = {
		.channels = BIT(spec.channel),
		.buffer = &buf,
		.buffer_size = sizeof(buf),
		.resolution = spec.resolution,
	};

	/* Main read loop */
	while (1) {
		/* Acquire the ADC sample */
		ret = adc_read_dt(&spec, &seq);
		if (ret) {
			printk("adc_read_dt failed: %d\n", ret);
		} else {
			/* Convert raw value to millivolts */
			int32_t mv = adc_raw_to_millivolts_dt(&spec, buf);
			printk("ADC value: %d mV\n", mv);
		}

		/* Delay 1 s before the next sample */
		K_MSLEEP(1000);
	}

	return 0;
}
